import{et as e,mt as t,s as n,tt as r}from"./chunks/framework.C92HYyu1.js";var i=JSON.parse(`{"title":"AI-Native Next-Gen Enterprise CMS | SyncCMS","description":"SyncCMS is an enterprise-grade hybrid headless CMS combining modern web technologies with on-premise private AI.","frontmatter":{"title":"AI-Native Next-Gen Enterprise CMS | SyncCMS","description":"SyncCMS is an enterprise-grade hybrid headless CMS combining modern web technologies with on-premise private AI.","sort":1,"head":[["link",{"rel":"canonical","href":"https://empasy.io/docs/en/synccms/"}]]},"headers":[],"relativePath":"en/synccms/index.md","filePath":"en/synccms/index.md","lastUpdated":1787437905000}`),a={name:`en/synccms/index.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<h1 id="synccms-enterprise-ai-hybrid-headless-cms" tabindex="-1">SyncCMS: Enterprise AI Hybrid Headless CMS <a class="header-anchor" href="#synccms-enterprise-ai-hybrid-headless-cms" aria-label="Permalink to “SyncCMS: Enterprise AI Hybrid Headless CMS”">​</a></h1><p><strong>SyncCMS</strong> is a next-generation enterprise AI hybrid headless content management platform that centrally controls all corporate digital touchpoints—web portals, mobile apps, kiosks, and internal intranets—from a single hub.</p><p>Overcoming the vendor lock-in of foreign SaaS and the legacy burden of monolithic CMSs, <strong>SyncCMS provides 100% transparent business source code and DB DDL, transforming the deployed solution into the client&#39;s permanent digital software asset.</strong></p><hr><h2 id="_3-core-enterprise-value-pillars" tabindex="-1">3 Core Enterprise Value Pillars <a class="header-anchor" href="#_3-core-enterprise-value-pillars" aria-label="Permalink to “3 Core Enterprise Value Pillars”">​</a></h2><ol><li><strong>Hybrid Headless DX</strong>: Headless REST API flexibility + Sync-Live-SDK real-time inline editing on live frontend screens.</li><li><strong>On-Premise Private AI Security</strong>: LangChain4j-powered private LLM (Llama-3, EXAONE) with real-time PII de-identification masking.</li><li><strong>Complete Technology Sovereignty</strong>: 100% transparent source code delivery, no vendor lock-in, and zero recurring license fees.</li></ol><hr><h2 id="technical-documentation-index" tabindex="-1">Technical Documentation Index <a class="header-anchor" href="#technical-documentation-index" aria-label="Permalink to “Technical Documentation Index”">​</a></h2><ol><li><a href="/docs/synccms/architecture">System Architecture</a> : Clean Architecture 4-layer overview and tech stack</li><li><a href="/docs/synccms/live-sdk-guide">Sync-Live-SDK Integration Guide</a> : 1-line script embedding &amp; inline live editing</li><li><a href="/docs/synccms/onpremise-ai-security">On-Premise AI &amp; Security</a> : On-premise LLMs &amp; real-time PII compliance</li><li><a href="/docs/synccms/integration-governance">Enterprise Governance &amp; Rollback</a> : Approval workflow &amp; snapshot 1-click rollback</li><li><a href="/docs/synccms/api-reference">Headless REST API Reference</a> : REST API specification and schema guide</li><li><a href="/docs/synccms/enterprise-faq">Enterprise FAQ &amp; Consultation</a> : Common questions &amp; architecture consultation</li></ol>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};